package ru.endlesscode.mimic.impl.mythicmobs

import org.bukkit.entity.Player
import org.bukkit.inventory.ItemStack
import ru.endlesscode.mimic.internal.NormalizedItemProvider

/**
 * Item provider for MythicMobs items, including items of MythicCrucible, see [NormalizedItemProvider] for item IDs.
 * An item created for a player is generated by MythicMobs for this player.
 */
internal class MythicMobsItemProvider(
    private val mythicMobs: MythicMobsWrapper = MythicMobsWrapper(),
) : NormalizedItemProvider("MythicMobs") {

    override val id: String = ID
    override val isEnabled: Boolean get() = mythicMobs.isEnabled

    override val nativeItemIds: Collection<String> get() = mythicMobs.itemIds

    override fun hasNativeItem(nativeId: String): Boolean = mythicMobs.hasItem(nativeId)

    override fun getNativeItemId(item: ItemStack): String? = mythicMobs.getItemId(item)

    override fun createNativeItem(nativeId: String, amount: Int, player: Player?): ItemStack? =
        mythicMobs.createItem(nativeId, amount, player)

    companion object {
        const val ID: String = "mythicmobs"
    }
}
